package fixture;
import java.util.*;import net.minecraft.nbt.*;import net.minecraft.core.*;import net.minecraft.world.item.ItemStack;import net.minecraft.world.entity.EquipmentSlot;import net.minecraft.world.level.GameRules;import net.minecraft.world.entity.item.ItemEntity;
public class Game{
 public static class Text{public String text;public Text(String s){text=s;}public String getString(){return text;}}
 public static class Level implements HolderLookup.Provider{public Map<UUID,Entity>entities=new HashMap<>();public List<de.maxhenkel.corpse.entities.CorpseEntity>corpses=new ArrayList<>();public boolean reject;public GameRules rules=new GameRules();public Object registryAccess(){return this;}public boolean isClientSide(){return false;}public Entity getEntity(UUID uuid){return entities.get(uuid);}public boolean addFreshEntity(de.maxhenkel.corpse.entities.CorpseEntity c){if(reject)return false;entities.put(c.uuid,c);corpses.add(c);return true;}public GameRules getGameRules(){return rules;}}
 public static class Entity{public UUID uuid=UUID.randomUUID();public Level world;public CompoundTag tag=new CompoundTag();public NonNullList<ItemStack>equipment=NonNullList.withSize(7,ItemStack.EMPTY);public String name="Survivor";public float yaw=42;public Entity(Level l){world=l;}public Level level(){return world;}public UUID getUUID(){return uuid;}public Text getName(){return new Text(name);}public CompoundTag getPersistentData(){return tag;}public double getX(){return 2;}public double getY(){return 65;}public double getZ(){return 3;}public float getYRot(){return yaw;}public void setPos(double x,double y,double z){}public void setYRot(float v){yaw=v;}public ItemStack getItemBySlot(EquipmentSlot s){return equipment.get(s.ordinal());}public void setItemSlot(EquipmentSlot s,ItemStack stack){equipment.set(s.ordinal(),stack);}public void setDropChance(EquipmentSlot s,float chance){if(chance!=0)throw new AssertionError();}public void setCanPickUpLoot(boolean b){}public void setPersistenceRequired(){}}
 public static class Zombie extends Entity implements net.smileycorp.hordes.common.entities.PlayerZombie{public UUID owner;public NonNullList<ItemStack>cargo=NonNullList.create();public Zombie(Level l){super(l);}public NonNullList<ItemStack>getInventory(){return cargo;}public Optional<UUID>getPlayerUUID(){return Optional.ofNullable(owner);}}
 public static class Cap{public Zombie zombie;public Zombie getZombie(){return zombie;}}
 public static class Cosmetic{public boolean failAfter;public NonNullList<ItemStack>items=NonNullList.withSize(4,ItemStack.EMPTY);public int getSlots(){return 4;}public ItemStack getStackInSlot(int i){return items.get(i);}public boolean isSkinArmor(int i){return false;}public void setStackInSlot(int i,ItemStack s){items.set(i,s);if(failAfter)throw new IllegalStateException("injected cosmetic listener failure");}}
 public static class Event{public Entity entity;public List<ItemEntity>drops=new ArrayList<>();public boolean canceled;public Event(Entity e){entity=e;}public Entity getEntity(){return entity;}public List<ItemEntity>getDrops(){return drops;}public void setCanceled(boolean b){canceled=b;}}
}
